package dev.zomboid.hordes;
import fixture.Game.*;import fixture.Game;import java.util.*;import net.minecraft.world.item.ItemStack;import dev.zomboid.remains.LootFinish15;
public class FinishChecks{
 static int checks;static void ok(boolean b,String reason){checks++;if(!b)throw new AssertionError(reason);}static List<ItemStack> items(Corpse b){return b.inventory.items.stream().filter(s->!s.isEmpty()).toList();}static long count(Corpse b,String id){return items(b).stream().filter(s->s.item.id.equals(id)).mapToLong(ItemStack::getCount).sum();}static boolean clothed(Corpse b){List<ItemStack>s=items(b);return s.stream().anyMatch(x->CorpseFinish45.slot(x).equals("chest"))&&s.stream().anyMatch(x->CorpseFinish45.slot(x).equals("legs"));}
 public static void main(String[]a)throws Exception{Game.register();World w=new World();Entity e=new Entity();Corpse b=new Corpse();b.inventory.setItem(0,Game.stack("minecraft:iron_axe"));b.inventory.setItem(1,Game.stack("minecraft:iron_axe",3));b.inventory.setItem(2,Game.stack("minecraft:diamond_axe"));b.inventory.setItem(3,Game.stack("minecraft:iron_pickaxe"));b.inventory.setItem(4,Game.stack("minecraft:coal",6));LootFinish15.finish(b,w,new Event(e));ok(clothed(b),"civilian clothing guaranteed even if panel path skipped professions");ok(count(b,"minecraft:iron_axe")+count(b,"minecraft:diamond_axe")==1,"one axe category despite material, wear and stack count");ok(count(b,"minecraft:iron_pickaxe")==1,"different tool category allowed");ok(count(b,"minecraft:coal")==6,"non-tool quantities untouched");ok(b.randomized&&b.lootFinal15&&b.inventory.dirty>0,"final normalization marks persistent corpse dirty");int last=0;for(int i=0;i<54;i++)if(!b.inventory.getItem(i).isEmpty())last=i;ok(last>=18,"sparse loot dispersed across whole inventory");
  for(String role:ProfessionCatalog.IDS){Corpse body=new Corpse();Entity z=new Entity();z.tag.putString("zh31_profession",role);LootFinish15.finish(body,w,new Event(z));ok(clothed(body),"guaranteed shirt and trousers for role "+role);}
  Entity police=new Entity();police.tag.putString("Skin","textures/zombie/police.png");ok(CorpseProfessions.recognize(police)==25,"actual native recognizer accepts police skin alias");int guns=0,bats=0,ammo=0;for(int i=0;i<100;i++){Corpse body=new Corpse();LootFinish15.finish(body,w,new Event(police));ok(clothed(body)&&count(body,"sophisticatedbackpacks:backpack")==1,"every police corpse has outfit and backpack");long gun=count(body,"tacz:modern_kinetic_gun"),bat=items(body).stream().filter(s->s.item.id.equals("lrtactical:melee")&&"lrtactical:baseball_bat".equals(s.data.get("MeleeWeaponId"))).count();ok(gun+bat==1,"police guaranteed one sidearm or bat");if(gun>0){guns++;ok(items(body).stream().filter(s->s.item.id.contains("kinetic_gun")).allMatch(s->s.gun.endsWith("pistol")),"no generated rifle in police kit");}if(bat>0)bats++;long bullets=count(body,"tacz:ammo");if(bullets>0){ammo++;ok(gun>0&&bullets>=2&&bullets<=6,"few compatible bullets only with gun");}}
  ok(guns>45&&bats>15&&ammo>5&&ammo<45,"police randomized pistol/bat and conditional ammunition");
  Entity doctor=new Entity();doctor.tag.putString("zh31_profession","doctor");Corpse medical=new Corpse();LootFinish15.finish(medical,w,new Event(doctor));ok(count(medical,"selfexpression:doctor_helmet")==1&&clothed(medical),"doctor hat no longer suppresses body clothes");
  Corpse mutant=new Corpse();mutant.mutant=true;mutant.inventory.setItem(0,Game.stack("firstaid:bandage"));LootFinish15.finish(mutant,w,new Event(e));ok(count(mutant,"firstaid:bandage")>=3&&count(mutant,"firstaid:plaster")>=2&&count(mutant,"firstaid:prophylactic_antibiotic")==1,"mutant minimum medical reward increased");ok(count(mutant,"tacz_turrets:electronic_scrap")>=2&&count(mutant,"minecraft:iron_ingot")>=3,"mutant materials increased");mutant.inventory.clearContent();LootFinish15.normalize(mutant,w);ok(items(mutant).isEmpty(),"empty looted corpse never refills on normalization");
  WorldTuning.values.put("cadaveres_medicinas",0.);WorldTuning.values.put("cadaveres_materiales",0.);Corpse disabled=new Corpse();disabled.mutant=true;LootFinish15.finish(disabled,w,new Event(e));ok(count(disabled,"firstaid:bandage")==0&&count(disabled,"tacz_turrets:electronic_scrap")==0,"zero medical/material categories disable mutant bonuses");WorldTuning.values.clear();WorldTuning.values.put("cadaveres_cantidad",0.);Corpse zero=new Corpse();zero.mutant=true;LootFinish15.finish(zero,w,new Event(e));ok(count(zero,"firstaid:bandage")==0&&count(zero,"minecraft:iron_ingot")==0,"zero amount also disables mutant bonuses");WorldTuning.values.clear();long scarce=0,normal=0;for(int preset:new int[]{0,2}){SimpleSettings.afterPreset(WorldTuning.values,preset);for(int i=0;i<50;i++){Corpse body=new Corpse();body.mutant=true;LootFinish15.finish(body,w,new Event(e));if(preset==0)scarce+=count(body,"firstaid:bandage");else normal+=count(body,"firstaid:bandage");}}ok(normal>100&&scarce<normal/5,"Desolado and Normal produce substantially different mutant medicine rewards");WorldTuning.values.clear();
  Tag tag=new Tag();dev.zomboid.remains.CorpseMeta31.write(b,tag);Corpse loaded=new Corpse();dev.zomboid.remains.CorpseMeta31.read(loaded,tag);ok(loaded.lootFinal15,"actual metadata writer and loader persist finalization flag");
  Corpse legacy=new Corpse();legacy.inventory.setItem(0,Game.stack("minecraft:iron_axe",5));LootFinish15.normalize(legacy,w);ok(clothed(legacy)&&count(legacy,"minecraft:iron_axe")==1,"legacy corpse repaired once on first search");legacy.inventory.clearContent();LootFinish15.normalize(legacy,w);ok(items(legacy).isEmpty(),"legacy repair cannot refill repeatedly");
  Corpse firstOpen=new Corpse();LootFinish15.repairOnOpen(firstOpen,w);ok(clothed(firstOpen)&&firstOpen.lootFinal15,"legacy opening repairs clothes even without Quietly");firstOpen.inventory.clearContent();LootFinish15.repairOnOpen(firstOpen,w);ok(items(firstOpen).isEmpty(),"opening finalized corpse does not refill");
  Corpse npc=new Corpse();npc.inventory.setItem(0,Game.stack("minecraft:iron_axe",3));LootFinish15.markNpc(npc);LootFinish15.normalize(npc,w);ok(count(npc,"minecraft:iron_axe")==3,"owned NPC cargo exempt from generated loot trimming");
  WorldTuning.file=java.nio.file.Files.createTempDirectory("loot45-world-").resolve("world.properties");WorldTuning.values.put("cadaver_pool_police_officer",3.);CorpseFinish45.migrate();ok(WorldTuning.values.get("cadaver_pool_police_officer")==5.&&WorldTuning.writes==1,"existing default police weight migrated and persisted");WorldTuning.values.put("cadaver_pool_police_officer",3.);CorpseFinish45.migrate();ok(WorldTuning.values.get("cadaver_pool_police_officer")==3.,"after migration even explicit admin weight 3 remains configurable");WorldTuning.values.put("cadaver_pool_police_officer",8.);CorpseFinish45.migrate();ok(WorldTuning.values.get("cadaver_pool_police_officer")==8.&&WorldTuning.writes==1,"manual admin weight preserved");ok(ProfessionCatalog.WEIGHTS[25]>ProfessionCatalog.WEIGHTS[35],"new default police pool more common than military");
  Entity screamer=new Entity();screamer.type="mutants_l4d2:screamer";ok(LootFinish15.mutant(false,new Event(screamer)),"addon screamer gets mutant corpse without modifying living stats");ok(!LootFinish15.mutant(false,new Event(e)),"civilian not converted into mutant");
  System.out.println("PROFESSION_FINAL_LOOT_CHECKS="+checks+" POLICE_GUNS="+guns+" BATS="+bats+" AMMO="+ammo);
 }
}
